head.script:
scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 재생성 대비: 기존 컴포넌트 있으면 삭제
    if (typeof input1 !== 'undefined') {
        input1.remove();
    }
    if (typeof button1 !== 'undefined') {
        button1.remove();
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let grp_comp = $c.gcm.getTestGroup();

    let strTarget = '';
    let strButton = '';
    let strInput = '';

    let strNameSpace = 'xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms"';

    strTarget += '<w2:scrollView '+strNameSpace+' id="" style="width: 500px;height: 300px;">';
    strTarget += '</w2:scrollView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "scrollView",
        strTarget,
        grp_comp
    );

    // scrollView 내부에 컴포넌트를 넣으려면 parent 를 scrollView 안의 container DOM("{id}_container")으로 지정
    let containerDom = document.getElementById(target1.id + "_container");

    strButton += '<w2:button '+strNameSpace+' style="width:80px; height:23px;" id="" label="button"></w2:button>';

    scwin.button1 = await $p.dynamicCreate(
        "button1",
        "button",
        strButton,
        containerDom
    );

    strInput += '<xf:input '+strNameSpace+' id="" style="width:144px; height:21px; " initValue="input"></xf:input>';

    scwin.input1 = await $p.dynamicCreate(
        "input1",
        "input",
        strInput,
        containerDom
    );   
}
